-- ---------- NEW bnx.install_default_categories ----------
create function bnx.install_default_categories(p_currency char(3) default null) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare cur char(3); d record; pid uuid; id_ uuid; v bigint; added int := 0; kept int := 0;
begin
  cur := coalesce(p_currency, (select f.reporting_currency from bnx.financial_policy f order by f.version desc limit 1), 'CAD');
  if not exists (select 1 from bnx.currency where code = cur) then perform bnx.fail('UNKNOWN_CURRENCY', 'P0422', cur); end if;
  for d in select * from bnx.default_category_tree() order by ord loop
    -- an active category of the same kind, currency and English name is reused (members' own categories are never duplicated)
    select l.id into id_ from bnx.ledger_account l
      join lateral (select cv.name_en, cv.state from bnx.category_version cv where cv.category_id = l.id
                     order by cv.valid_from_version desc limit 1) c on true
     where l.kind = d.kind and l.currency = cur and c.state = 'active' and lower(c.name_en) = lower(d.name_en)
     order by l.id limit 1;
    if id_ is not null then kept := kept + 1; continue; end if;
    pid := null;
    if d.parent_en is not null then
      select l.id into pid from bnx.ledger_account l
        join lateral (select cv.name_en, cv.state from bnx.category_version cv where cv.category_id = l.id
                       order by cv.valid_from_version desc limit 1) c on true
       where l.kind = d.kind and l.currency = cur and c.state = 'active' and lower(c.name_en) = lower(d.parent_en)
       order by l.id limit 1;
    end if;
    if v is null then v := bnx.next_version(); end if;
    id_ := gen_random_uuid();
    insert into bnx.ledger_account values (id_, d.kind, cur, d.name_en);
    insert into bnx.category_version values (id_, v, pid, d.name_en, d.name_zh, 'active');
    added := added + 1;
  end loop;
  if added > 0 then
    perform bnx.audit(row(null, null, 'installer', null, null)::bnx.actor, 'install_default_categories',
                      jsonb_build_object('currency', cur, 'added', added, 'kept', kept), '{}', v);
  end if;
  return jsonb_build_object('currency', cur, 'added', added, 'kept', kept, 'ledger_version', v);
end $$;

-- ---------- ALTER bnx_intake.account_proposal ----------
alter table bnx_intake.account_proposal add column suggested_kind text
  check (suggested_kind is null or suggested_kind in ('bank_deposit','e_wallet','credit_card','investment','loan_payable','loan_receivable'));
alter table bnx_intake.account_proposal add column suggested_label text check (suggested_label is null or length(suggested_label) between 1 and 80);
alter table bnx_intake.account_proposal add column opening jsonb;
alter table bnx_intake.account_proposal add column origin_connection_id uuid references bnx.ai_connection;

-- ---------- NEW bnx.cmd_propose_account_from_statement ----------
create function bnx.cmd_propose_account_from_statement(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); rc jsonb; ins record; kind text := cmd->>'kind'; l4 text := cmd->>'account_last4';
        cur text := cmd->>'currency'; sc text := cmd->>'sign_convention'; pf date; op numeric; lbl text; hs text[] := '{}';
        sid uuid; pid uuid; ex uuid; opening jsonb;
begin
  perform bnx.require(a, 1);
  rc := bnx.idem_begin(a, 'propose_account_from_statement', cmd); if rc is not null then return rc; end if;
  if coalesce(kind, '') not in ('bank_deposit','e_wallet','credit_card','investment','loan_payable','loan_receivable') then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'kind'); end if;
  if coalesce(l4, '') !~ '^[0-9]{4}$' then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_last4'); end if;
  if not exists (select 1 from bnx.currency where code = cur) then perform bnx.fail('UNKNOWN_CURRENCY', 'P0422', cur); end if;
  begin
    select * into ins from bnx.institution where id = (cmd->>'institution_id')::uuid;
  exception when invalid_text_representation then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'institution_id'); end;
  if ins.id is null or ins.status not in ('ACTIVE_SEED','VERIFIED_ACTIVE') then perform bnx.fail('INSTITUTION_NOT_ELIGIBLE', 'P0422'); end if;
  lbl := nullif(btrim(coalesce(cmd->>'label', '')), '');
  if lbl is not null and length(lbl) > 80 then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'label'); end if;
  lbl := coalesce(lbl, coalesce(ins.code, ins.name_en) || ' ' ||
         case kind when 'credit_card' then 'card' when 'bank_deposit' then 'account' else replace(kind, '_', ' ') end || ' ' || l4);
  if cmd ? 'holder_names' then
    if jsonb_typeof(cmd->'holder_names') <> 'array' or jsonb_array_length(cmd->'holder_names') > 4 then
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'holder_names'); end if;
    hs := array(select btrim(x) from jsonb_array_elements_text(cmd->'holder_names') x where btrim(x) <> '');
    if exists (select 1 from unnest(hs) x where length(x) > 80 or x ~ '[0-9]{3}') then
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'holder_names'); end if;
  end if;
  -- the first statement's opening balance becomes the opening anchor on approval (ledger sign; cards and loans owed-positive)
  if cmd ? 'opening_balance' or cmd ? 'period_from' then
    begin pf := (cmd->>'period_from')::date; op := (cmd->>'opening_balance')::numeric;
    exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'period_from, opening_balance'); end;
    if pf is null or op is null or coalesce(sc, '') not in ('asset_positive','owed_positive') then
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'period_from, opening_balance, sign_convention'); end if;
    perform bnx.assert_scale(op, cur, 'opening_balance');
    opening := jsonb_build_object('anchor_date', pf, 'amount', trim_scale(case when sc = 'owed_positive' then -op else op end)::text,
                                  'printed_opening', trim_scale(op)::text, 'sign_convention', sc);
  end if;
  -- an existing account is never proposed again; its existence is all the caller learns (no id, no label)
  if exists (select 1 from bnx.account acc join bnx.account_currency ac on ac.account_id = acc.id
              where acc.institution_id = ins.id and acc.state = 'active' and ac.currency = cur
                and right(regexp_replace(coalesce(acc.masked_display, acc.reference_display, ''), '[^0-9]', '', 'g'), 4) = l4) then
    perform bnx.fail('ACCOUNT_EXISTS', 'P0409'); end if;
  select p.id into ex from bnx_intake.account_proposal p
   where p.state = 'PROPOSED' and p.institution_id = ins.id and cur = any(p.currencies)
     and right(regexp_replace(coalesce(p.reference_display, ''), '[^0-9]', '', 'g'), 4) = l4
   order by p.created_at limit 1;
  if ex is not null then
    return bnx.idem_end(a, 'propose_account_from_statement', cmd, jsonb_build_object('proposal_id', ex, 'state', 'PROPOSED', 'existing', true));
  end if;
  insert into bnx_intake.account_identity_signal(institution_id, masked_reference, holder_names, currency, period_start, opening_balance, uploaded_by)
  values (ins.id, '****' || l4, hs, cur, pf, op, a.member_id) returning id into sid;
  insert into bnx_intake.account_proposal(confidence, rule_codes, match_trace, institution_id, reference_display, holder_names, currencies,
                                          signal_ids, created_by, suggested_kind, suggested_label, opening, origin_connection_id)
  values ('high', array['AI-STMT'], jsonb_build_object('source', 'ai_statement', 'channel', a.channel), ins.id, '•••• ' || l4, hs,
          array[cur]::char(3)[], array[sid], a.member_id, kind, lbl, opening, a.connection_id) returning id into pid;
  perform bnx.audit(a, 'propose_account_from_statement', jsonb_build_object('proposal_id', pid), cmd, null);
  return bnx.idem_end(a, 'propose_account_from_statement', cmd, jsonb_build_object('proposal_id', pid, 'state', 'PROPOSED', 'existing', false,
           'suggested_kind', kind, 'suggested_label', lbl, 'opening', opening));
end $$;

-- ---------- MODIFY bnx.cmd_resolve_account_proposal (9010) ----------
-- never automatic: approval creates the account through cmd_create_account (same tables, grants and registry rules)
create or replace function bnx.cmd_resolve_account_proposal(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); rc jsonb; p record; t record; r jsonb := '{}'; act text := cmd->>'action';
        acid uuid; granted boolean := false;                                                                              -- 9045
begin
  perform bnx.require(a, 2);
  rc := bnx.idem_begin(a, 'resolve_account_proposal', cmd); if rc is not null then return rc; end if;
  select * into p from bnx_intake.account_proposal where id = (cmd->>'proposal_id')::uuid for update;
  if not found then perform bnx.fail('NOT_FOUND', 'P0404'); end if;
  if p.state <> 'PROPOSED' then perform bnx.fail('PROPOSAL_NOT_OPEN', 'P0409', p.state); end if;
  if act = 'approve' then
    r := bnx.cmd_create_account(cred, jsonb_strip_nulls(jsonb_build_object('idempotency_key', 'acct-proposal-' || p.id,
           'kind', coalesce(cmd->>'kind', p.suggested_kind), 'institution_id', coalesce(cmd->>'institution_id', p.institution_id::text),  -- 9045
           'label', coalesce(nullif(btrim(cmd->>'label'), ''), p.suggested_label),                                          -- 9045
           'currencies', to_jsonb(p.currencies), 'visibility', cmd->>'visibility', 'region_scope', cmd->>'region_scope',
           'masked_display', p.reference_display)));
    update bnx_intake.account_proposal set state = 'APPROVED', account_id = (r->>'account_id')::uuid, decided_by = a.member_id, decided_at = now()
     where id = p.id;
    acid := (r->'account_currencies'->0->>'account_currency_id')::uuid;                                                 -- 9045
    -- the first statement's opening balance becomes the opening anchor (the member may decline it)                    -- 9045
    if p.opening is not null and coalesce(cmd->>'set_opening', 'true') <> 'false' and acid is not null then            -- 9045
      perform bnx.cmd_set_opening(cred, jsonb_build_object('idempotency_key', 'acct-proposal-opening-' || p.id,      -- 9045
        'account_currency_id', acid, 'anchor_date', p.opening->>'anchor_date', 'amount', p.opening->>'amount',         -- 9045
        'reason', 'opening balance of the first statement', 'certainty', 'declared'));                                  -- 9045
    end if;                                                                                                              -- 9045
    -- the AI connection that proposed the account may see it (second step: it submits the statement); default yes     -- 9045
    if p.origin_connection_id is not null and coalesce(cmd->>'grant_connection', 'true') <> 'false' then                -- 9045
      update bnx.ai_connection set account_currency_ids = array(select distinct x from unnest(account_currency_ids || -- 9045
               array(select (e->>'account_currency_id')::uuid from jsonb_array_elements(r->'account_currencies') e)) x) -- 9045
       where id = p.origin_connection_id and revoked_at is null and member_id = a.member_id;                            -- 9045
      if found then                                                                                                     -- 9045
        granted := true;                                                                                                 -- 9045
        insert into bnx.ai_connection_subset(connection_id, kind, value)                                                -- 9045
        select p.origin_connection_id, 'account_currency', e->>'account_currency_id'                                    -- 9045
          from jsonb_array_elements(r->'account_currencies') e on conflict do nothing;                                  -- 9045
      end if;                                                                                                            -- 9045
    end if;                                                                                                              -- 9045
  elsif act = 'reject' then
    update bnx_intake.account_proposal set state = 'REJECTED', decided_by = a.member_id, decided_at = now() where id = p.id;
  elsif act = 'merge' then
    select * into t from bnx_intake.account_proposal where id = (cmd->>'merge_into')::uuid for update;
    if t.id is null or t.state <> 'PROPOSED' or t.id = p.id then perform bnx.fail('PROPOSAL_NOT_OPEN', 'P0409', 'merge target'); end if;
    update bnx_intake.account_proposal set signal_ids = array(select distinct unnest(t.signal_ids || p.signal_ids)),
           currencies = array(select distinct unnest(t.currencies || p.currencies) order by 1),
           holder_names = array(select distinct unnest(t.holder_names || p.holder_names) order by 1),
           rule_codes = array(select distinct unnest(t.rule_codes || p.rule_codes) order by 1),
           match_trace = t.match_trace || jsonb_build_object('merged_by_member', p.id) where id = t.id;
    update bnx_intake.account_proposal set state = 'MERGED', merged_into = t.id, decided_by = a.member_id, decided_at = now() where id = p.id;
  else perform bnx.fail('VALIDATION_FAILED', 'P0422', 'action');
  end if;
  perform bnx.audit(a, 'resolve_account_proposal', jsonb_build_object('proposal_id', p.id, 'action', act), cmd, null);
  return bnx.idem_end(a, 'resolve_account_proposal', cmd, jsonb_build_object('proposal_id', p.id, 'action', act)
         || case when r ? 'account_id' then jsonb_build_object('account_id', r->>'account_id', 'account_currencies', r->'account_currencies',
                 'opening_set', p.opening is not null and coalesce(cmd->>'set_opening', 'true') <> 'false',              -- 9045
                 'connection_granted', granted) else '{}' end);                                                            -- 9045
end $$;

-- ---------- MODIFY bnx.q_account_proposals (9010) ----------
create or replace function bnx.q_account_proposals(cred jsonb, q jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred);
begin
  perform bnx.require(a, 0);
  return jsonb_build_object('proposals', coalesce((select jsonb_agg(jsonb_build_object('proposal_id', p.id, 'state', p.state, 'confidence', p.confidence,
           'rule_codes', to_jsonb(p.rule_codes), 'identity_conflict', p.identity_conflict, 'institution_id', p.institution_id,
           'reference_display', p.reference_display, 'currencies', to_jsonb(p.currencies), 'holder_names', to_jsonb(p.holder_names),
           'signal_count', cardinality(p.signal_ids), 'match_trace', p.match_trace, 'account_id', p.account_id,
           'institution', i.name_en, 'institution_code', i.code, 'suggested_kind', p.suggested_kind,                      -- 9045
           'suggested_label', p.suggested_label, 'opening', p.opening, 'created_at', p.created_at,                        -- 9045
           'origin_client', o.display_name)                                                                               -- 9045
           order by case p.confidence when 'high' then 1 when 'medium' then 2 else 3 end, p.created_at, p.id)
      from bnx_intake.account_proposal p
      left join bnx.institution i on i.id = p.institution_id                                                              -- 9045
      left join bnx.ai_connection c on c.id = p.origin_connection_id                                                       -- 9045
      left join bnx.oauth_client o on o.client_id = c.client_id                                                            -- 9045
     where p.state = coalesce(q->>'state', p.state)
       and (a.channel <> 'mcp' or p.origin_connection_id = a.connection_id)), '[]'));                                     -- 9045
end $$;

-- ---------- MODIFY bnx.q_ledger_accounts (9019) ----------
create or replace function bnx.q_ledger_accounts(cred jsonb, q jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); acs jsonb; cats jsonb;
begin
  perform bnx.require(a, 0);
  select coalesce(jsonb_agg(jsonb_build_object('account_currency_id', ac.id, 'ledger_account_id', ac.ledger_account_id, 'account_id', acc.id,
           'label', acc.label, 'kind', acc.kind, 'currency', ac.currency, 'state', acc.state, 'institution_code', i.code,
           'institution', i.name_en, 'can_post', bnx.actor_can_post(a, ac.id),
           'reference_display', coalesce(acc.masked_display, acc.reference_display))                                     -- 9045
           order by acc.state, i.code nulls last, acc.label, ac.currency), '[]')
    into acs
    from bnx.actor_visible_acs(a) x join bnx.account_currency ac on ac.id = x join bnx.account acc on acc.id = ac.account_id
    left join bnx.institution i on i.id = acc.institution_id;
  select coalesce(jsonb_agg(jsonb_build_object('ledger_account_id', l.id, 'kind', l.kind, 'currency', l.currency,
           'name_en', c.name_en, 'name_zh', c.name_zh, 'parent_id', c.parent_id)                                          -- 9045
           order by l.kind, l.currency, c.name_en), '[]')
    into cats
    from bnx.ledger_account l
    join lateral (select cv.name_en, cv.name_zh, cv.state, cv.parent_id from bnx.category_version cv where cv.category_id = l.id  -- 9045
                   order by cv.valid_from_version desc limit 1) c on true
   where l.kind in ('income','expense') and c.state = 'active';
  return jsonb_build_object('accounts', acs, 'categories', cats);
end $$;

-- ---------- MODIFY bnx.q_draft_get_for_confirmation (9010) ----------
create or replace function bnx.q_draft_get_for_confirmation(cred jsonb, q jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); pl record;
        acc record;                                                                                                        -- 9045
begin
  perform bnx.require(a, case when a.channel = 'mcp' then 1 else 0 end);
  select * into pl from bnx.posting_plan where id = (q->>'plan_id')::uuid;
  if not found or not ((pl.scope->>'account_currency_id')::uuid in (select bnx.actor_visible_acs(a)))
     or (a.channel = 'mcp' and pl.origin_ai_connection_id is distinct from a.connection_id) then
    perform bnx.fail('NOT_AVAILABLE', 'P0404'); end if;
  select ac.id, ac.currency, x.label, x.masked_display into acc from bnx.account_currency ac                                -- 9045
    join bnx.account x on x.id = ac.account_id where ac.id = (pl.scope->>'account_currency_id')::uuid;                     -- 9045
  return jsonb_build_object('plan_id', pl.id, 'kind', pl.kind, 'state', pl.state, 'plan_hash', encode(pl.plan_hash, 'hex'),
    'scope_digest', encode(pl.scope_digest, 'hex'), 'validation_result', pl.validation_result, 'hold_reasons', to_jsonb(pl.hold_reasons),
    'created_by', pl.created_by, 'origin_channel', pl.origin_channel,
    'account_currency_id', acc.id, 'account_label', acc.label, 'account_currency', acc.currency,                         -- 9045
    'account_reference_display', acc.masked_display, 'statement', pl.scope->'statement',                                -- 9045
    'items', (select jsonb_agg(jsonb_build_object('seq', i.seq, 'payload', i.payload, 'economic_type', bnx.plan_item_economic_type(i.payload),
                                                  'lines', (select jsonb_agg(l || jsonb_build_object(                     -- 9045
                                                     'ledger_account_name', bnx.ledger_account_display(l->>'ledger_account_id', 'en'),  -- 9045
                                                     'ledger_account_name_zh', bnx.ledger_account_display(l->>'ledger_account_id', 'zh')) -- 9045
                                                     order by n)                                                          -- 9045
                                                     from jsonb_array_elements(bnx.plan_item_lines(pl.id, i.payload)) with ordinality e(l, n))) -- 9045
                                  order by i.seq)
                from bnx.posting_plan_item i where i.plan_id = pl.id),
    'approvable_by_me', a.channel = 'pwa' and bnx.actor_can_post(a, (pl.scope->>'account_currency_id')::uuid)
                        and pl.state = 'frozen' and cardinality(pl.hold_reasons) = 0);
end $$;

-- the name a member reads for a ledger account: the account's label for an account-currency, "Parent › Child" for a category,
-- the stored name otherwise (system accounts); never a number beyond the masked last four of the label
create function bnx.ledger_account_display(p_id text, p_lang text) returns text
language sql stable security definer set search_path = pg_catalog, pg_temp as $$
  select coalesce(
    (select acc.label from bnx.account_currency ac join bnx.account acc on acc.id = ac.account_id
      where ac.ledger_account_id::text = p_id limit 1),
    (select case when c.parent_id is null then cn
                 else coalesce((select case when p_lang = 'zh' then pv.name_zh else pv.name_en end from bnx.category_version pv
                                 where pv.category_id = c.parent_id order by pv.valid_from_version desc limit 1) || ' › ', '') || cn end
       from (select cv.parent_id, case when p_lang = 'zh' then cv.name_zh else cv.name_en end cn from bnx.category_version cv
              where cv.category_id::text = p_id order by cv.valid_from_version desc limit 1) c),
    (select l.name from bnx.ledger_account l where l.id::text = p_id))
$$;

